import type { Currency, InsightType } from "@/lib/generated/prisma/client";

/**
 * Result of AI categorization.
 */
export type CategorySuggestionResult = {
  categoryId: string;
  categoryName: string;
  confidence: number; // 0.0 to 1.0
  reason: string;
  isFromLocalMemory?: boolean;
};

/**
 * Single structured insight generated by AI from verified math.
 */
export type GeneratedInsightItem = {
  type: InsightType;
  title: string;
  summary: string;
  actionableStep?: string;
  reasoning: Record<string, unknown>;
};

/**
 * Compact living memory of user's financial habits and context (~50-80 tokens).
 */
export type UserFinancialMemory = {
  merchantHabits: Record<string, string>; // e.g. { "carrefour": "Food & Dining", "total": "Transportation" }
  activeGoalsSummary?: string; // e.g. "Emergency Fund at 45% (target 100k KES)"
  priorMonthTrajectory?: string; // e.g. "Oct: +8.5k net cash flow, transport was over-budget"
  primaryCurrency: Currency;
};

/**
 * Input for monthly insight generation.
 */
export type MonthlyInsightInput = {
  period: { year: number; month: number };
  currency: Currency;
  summary: {
    income: string;
    spending: string;
    saved: string;
    invested: string;
    netCashFlow: string;
    topCategories: Array<{ name: string; amount: string }>;
  };
  budget?: {
    totalAllocated: string;
    totalActual: string;
    overBudgetCategories: Array<{ name: string; allocated: string; actual: string }>;
  } | null;
  goals: Array<{
    name: string;
    currentAmount: string;
    targetAmount: string;
    percentComplete: string;
    status: string;
  }>;
  memory?: UserFinancialMemory;
};
